import { describe, expect, test } from 'vitest';
import { readFileSync, existsSync, statSync, readdirSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse as parseYaml } from 'yaml';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const REPO_ROOT = resolve(__dirname, '..', '..', '..');

const repoPath = (rel: string): string => resolve(REPO_ROOT, rel);
const repoFileExists = (rel: string): boolean => existsSync(repoPath(rel));
const readRepoFile = (rel: string): string => readFileSync(repoPath(rel), 'utf8');
const loadYaml = <T = unknown>(rel: string): T => parseYaml(readRepoFile(rel)) as T;

// ------------------------------------------------------------
// Story-1.7-specific helpers
// ------------------------------------------------------------
const APPS_DIR = 'infra/argocd/applications';
const HELM_DIR = 'infra/helm';
const BUILD_WF = '.github/workflows/build-images.yml';
const DEPLOY_WF = '.github/workflows/deploy-staging.yml';
const STORY = 'docs/stories/1.7-staging-deploy-pipeline-wiring.md';
const REPO_URL = 'https://github.com/he-api/he-api';
const SAMPLES = ['sample-otel-app', 'sample-grpc-app'];

const listAppFiles = (): string[] =>
  readdirSync(repoPath(APPS_DIR))
    .filter((f) => f.endsWith('.yaml'))
    .sort();

const loadApp = (file: string): any => loadYaml(`${APPS_DIR}/${file}`);
const allApps = (): any[] => listAppFiles().map(loadApp);

const helmCharts = (): string[] =>
  readdirSync(repoPath(HELM_DIR)).filter((d) => existsSync(repoPath(`${HELM_DIR}/${d}/Chart.yaml`)));

// Recursive Dockerfile finder under apps/.
const findDockerfiles = (rel: string): string[] => {
  const out: string[] = [];
  for (const entry of readdirSync(repoPath(rel), { withFileTypes: true })) {
    const child = join(rel, entry.name);
    if (entry.isDirectory()) out.push(...findDockerfiles(child));
    else if (entry.name === 'Dockerfile') out.push(child);
  }
  return out;
};

const buildWf = (): any => loadYaml(BUILD_WF);
const prMatrix = (): any[] => buildWf().jobs['build-image-pr'].strategy.matrix.svc;
const nonSampleMatrix = (): any[] => prMatrix().filter((e) => e.sample !== true);

// values*.yaml across all charts.
const valuesFiles = (): string[] => {
  const out: string[] = [];
  for (const c of readdirSync(repoPath(HELM_DIR))) {
    for (const f of ['values.yaml', 'values-staging.yaml']) {
      if (existsSync(repoPath(`${HELM_DIR}/${c}/${f}`))) out.push(`${HELM_DIR}/${c}/${f}`);
    }
  }
  return out;
};

// Collect every image.tag value reachable in a parsed values object (main + cron sub-images).
const collectTags = (node: any, acc: string[] = []): string[] => {
  if (node && typeof node === 'object') {
    if (typeof node.repository === 'string' && node.tag !== undefined) acc.push(String(node.tag));
    for (const v of Object.values(node)) collectTags(v, acc);
  }
  return acc;
};
const collectRepositories = (node: any, acc: string[] = []): string[] => {
  if (node && typeof node === 'object') {
    if (typeof node.repository === 'string') acc.push(node.repository);
    for (const v of Object.values(node)) collectRepositories(v, acc);
  }
  return acc;
};

const PLACEHOLDER = 'ArgoCD sync placeholder (real CLI wired in Story 1.4)';

// ============================================================
// AC1 (B1): ArgoCD 同步换成真实 `argocd app sync`
// ============================================================

describe('AC1 (B1): real argocd app sync', () => {
  test('1.7-UNIT-001: ArgoCD sync placeholder string removed repo-wide (grep 0 hits)', () => {
    expect(readRepoFile(DEPLOY_WF)).not.toContain(PLACEHOLDER);
    expect(readRepoFile(DEPLOY_WF)).not.toContain('real CLI wired in Story 1.4');
  });

  test('1.7-UNIT-002: deploy-staging trigger-argocd-sync runs real `argocd app sync` + `argocd app wait --health`', () => {
    const wf = readRepoFile(DEPLOY_WF);
    expect(wf).toMatch(/argocd app sync/);
    expect(wf).toMatch(/argocd app wait/);
    expect(wf).toMatch(/--health/);
    expect(wf).not.toMatch(/echo "ArgoCD sync placeholder/);
  });

  test('1.7-UNIT-003: argocd login uses secrets.ARGOCD_AUTH_TOKEN + vars.ARGOCD_ENDPOINT, --grpc-web, no plaintext/hardcoded creds', () => {
    const wf = readRepoFile(DEPLOY_WF);
    expect(wf).toContain('secrets.ARGOCD_AUTH_TOKEN');
    expect(wf).toContain('vars.ARGOCD_ENDPOINT');
    expect(wf).toContain('--grpc-web');
    // No hardcoded argocd endpoint URL, no plaintext token flag.
    expect(wf).not.toMatch(/--server\s+https?:\/\//);
    expect(wf).not.toMatch(/--auth-token\s+\S/);
    expect(wf).not.toContain('--plaintext');
  });

  test('1.7-UNIT-005: deploy-staging.yml passes actionlint / YAML parse', () => {
    expect(() => loadYaml(DEPLOY_WF)).not.toThrow();
  });

  test('1.7-INT-001: sync target app list == infra/argocd/applications/*.yaml inventory (single source)', () => {
    const wf = readRepoFile(DEPLOY_WF);
    // The sync step derives names from the Application inventory dir (single source, BR1.4).
    expect(wf).toContain(APPS_DIR);
    expect(wf).toMatch(/argocd app sync "\$name"/);
    expect(listAppFiles().length).toBeGreaterThanOrEqual(13);
  });

  test('[BLIND-SPOT] 1.7-BLIND-ERROR-001: argocd login failure → non-zero exit, job fails, does NOT enter sync', () => {
    const wf = readRepoFile(DEPLOY_WF);
    // Login is a separate, earlier step that validates the session (get-user-info)
    // under `set -euo pipefail`; a bad token/endpoint fails before any sync step.
    expect(wf).toMatch(/ArgoCD login[\s\S]*set -euo pipefail[\s\S]*get-user-info/);
    expect(wf.indexOf('get-user-info')).toBeLessThan(wf.indexOf('argocd app sync'));
  });

  test('[BLIND-SPOT] 1.7-BLIND-ERROR-002: app sync/wait timeout or unhealthy → job fails (non-zero), error not swallowed', () => {
    const wf = readRepoFile(DEPLOY_WF);
    // rc accumulator + explicit exit "$rc" → a failed sync/wait fails the job.
    expect(wf).toMatch(/argocd app wait[\s\S]*--health/);
    expect(wf).toMatch(/rc=1/);
    expect(wf).toMatch(/exit "\$rc"/);
  });

  test('[BLIND-SPOT] 1.7-BLIND-BOUNDARY-001: ARGOCD_ENDPOINT empty/unset (HAS_ARGOCD != true) → skip message, not crash', () => {
    const wf = readRepoFile(DEPLOY_WF);
    expect(wf).toContain("HAS_ARGOCD: ${{ vars.ARGOCD_ENDPOINT != '' && 'true' || 'false' }}");
    expect(wf).toMatch(/Skip ArgoCD sync \(fallback\)/);
  });

  test('[BLIND-SPOT] 1.7-BLIND-FLOW-001: HAS_ARGOCD != true → fallback skip step preserved (no-creds CI not broken)', () => {
    const wf = readRepoFile(DEPLOY_WF);
    expect(wf).toMatch(/if: env\.HAS_ARGOCD != 'true'/);
  });
});

// ============================================================
// AC2 (B2): build-images 矩阵覆盖全部可部署镜像
// ============================================================

describe('AC2 (B2): build-images matrix covers all deployable images', () => {
  test('1.7-UNIT-010: &svc_list anchor extended; pr+main matrices share single anchor (1.5-UNIT-216 no regression)', () => {
    const raw = readRepoFile(BUILD_WF);
    // Exactly one anchor DEFINITION (`svc: &svc_list`) and one ALIAS reuse
    // (`svc: *svc_list`) — the single-append-point contract. (Comments may
    // mention the anchor name; match the structural form, not bare mentions.)
    expect((raw.match(/svc: &svc_list/g) || []).length).toBe(1);
    expect((raw.match(/svc: \*svc_list/g) || []).length).toBe(1);
    // Resolved anchor → pr and main matrices are identical.
    const wf = buildWf();
    expect(wf.jobs['build-image-main'].strategy.matrix.svc).toEqual(
      wf.jobs['build-image-pr'].strategy.matrix.svc,
    );
  });

  test('1.7-UNIT-011: main-branch push tags images :${github.sha} (immutable, no latest)', () => {
    const raw = readRepoFile(BUILD_WF);
    expect(raw).toMatch(/tags: \$\{\{ secrets\.ACR_REGISTRY \}\}\/he-api\/\$\{\{ matrix\.svc\.name \}\}:\$\{\{ github\.sha \}\}/);
    expect(raw).not.toMatch(/:latest/);
  });

  test('1.7-UNIT-012: cron images with context != apps/<svc> carry explicit context/dockerfile matrix-include fields', () => {
    for (const e of prMatrix()) {
      expect(typeof e.context).toBe('string');
      expect(typeof e.dockerfile).toBe('string');
    }
  });

  test('1.7-UNIT-013: sample-otel-app / sample-grpc-app retained in matrix but excluded from the 17 count', () => {
    const names = prMatrix().map((e) => e.name);
    for (const s of SAMPLES) expect(names).toContain(s);
    for (const e of prMatrix().filter((x) => SAMPLES.includes(x.name))) expect(e.sample).toBe(true);
    expect(nonSampleMatrix().some((e) => SAMPLES.includes(e.name))).toBe(false);
  });

  test('1.7-UNIT-014: image-sha artifact upload preserved; deploy-staging download step not broken', () => {
    const build = readRepoFile(BUILD_WF);
    expect(build).toContain('upload-artifact');
    expect(build).toMatch(/name: image-sha/);
    expect(build).toMatch(/if: matrix\.svc\.name == 'api-gateway'/);
    const deploy = readRepoFile(DEPLOY_WF);
    expect(deploy).toContain('download-artifact');
    expect(deploy).toMatch(/name: image-sha/);
  });

  test('1.7-INT-002: matrix entry count == authoritative apps/**/Dockerfile target count (17)', () => {
    const deployableDockerfiles = findDockerfiles('apps').filter(
      (d) => !SAMPLES.some((s) => d.includes(`/${s}/`)),
    );
    expect(deployableDockerfiles.length).toBe(17);
    expect(nonSampleMatrix().length).toBe(17);
  });

  test('[BLIND-SPOT] 1.7-BLIND-ERROR-003: single image build fails → fail-fast:false (others continue) BUT job overall fails', () => {
    const wf = buildWf();
    expect(wf.jobs['build-image-pr'].strategy['fail-fast']).toBe(false);
    expect(wf.jobs['build-image-main'].strategy['fail-fast']).toBe(false);
  });

  test('[BLIND-SPOT] 1.7-BLIND-FLOW-002: HAS_ACR != true → skip-push branch preserved (no-creds CI only validates)', () => {
    const raw = readRepoFile(BUILD_WF);
    expect(raw).toMatch(/Skip push \(no ACR secrets\)/);
    expect(raw).toMatch(/if: env\.HAS_ACR != 'true'/);
  });

  test('[BLIND-SPOT] 1.7-BLIND-DATA-001: every build-matrix entry resolves to an existing Dockerfile (no orphan/unbuildable entry)', () => {
    for (const e of prMatrix()) {
      expect(repoFileExists(e.dockerfile), `dockerfile missing: ${e.dockerfile}`).toBe(true);
    }
  });
});

