// ============================================================
// AC4 (B4): 消除镜像占位符与 `tag: latest`
// ============================================================

describe('AC4 (B4): eliminate image placeholders and tag:latest', () => {
  test('1.7-UNIT-030: grep — no `tag: latest` / moving tag in any values*.yaml (0 hits)', () => {
    for (const f of valuesFiles()) {
      for (const tag of collectTags(loadYaml<any>(f))) {
        expect(tag, `${f} has moving tag`).not.toBe('latest');
      }
    }
  });

  test('1.7-UNIT-031: image repository placeholder syntax unified to ONE convention repo-wide (no $$ vs ${} split)', () => {
    for (const f of valuesFiles()) {
      for (const repo of collectRepositories(loadYaml<any>(f))) {
        expect(repo, `${f} uses double-dollar placeholder`).not.toContain('$$');
      }
    }
  });

  test('1.7-UNIT-032: deploy-staging update-helm-values bumps ALL staging apps image.tag = ${github.sha} (not just api-gateway)', () => {
    const wf = readRepoFile(DEPLOY_WF);
    // Loops over the Application inventory and recursively bumps every image tag.
    expect(wf).toContain(APPS_DIR);
    expect(wf).toMatch(/select\(has\("repository"\) and has\("tag"\)\) \| \.tag\) = strenv\(SHA\)/);
    // No longer a single hardcoded api-gateway-only bump.
    expect(wf).not.toMatch(/yq eval -i '\.image\.tag = strenv\(SHA\)' infra\/helm\/api-gateway\/values-staging\.yaml/);
  });

  test('1.7-UNIT-033: values.yaml (default) keeps semver; only values-staging.yaml SHA-bumped', () => {
    // Default values.yaml tags are semver-ish (no token, no 40-hex SHA).
    for (const c of helmCharts()) {
      const vf = `${HELM_DIR}/${c}/values.yaml`;
      if (!repoFileExists(vf)) continue;
      for (const tag of collectTags(loadYaml<any>(vf))) {
        expect(tag, `${vf} default tag should be semver`).toMatch(/^\d+\.\d+\.\d+$/);
      }
    }
    // The bump workflow only writes values-staging.yaml, never values.yaml.
    const wf = readRepoFile(DEPLOY_WF);
    expect(wf).toMatch(/values-staging\.yaml/);
    expect(wf).not.toMatch(/yq -i[^\n]*\/values\.yaml/);
  });

  test('1.7-UNIT-034: api-gateway values-staging whitelist comment updated for expanded bump scope; image.tag stays yq-writable', () => {
    const raw = readRepoFile('infra/helm/api-gateway/values-staging.yaml');
    expect(raw).toMatch(/1\.7/);
    expect(raw).toMatch(/ingress/i);
    // image.tag is a plain quoted scalar (yq-writable), not a Helm/templated value.
    const v = loadYaml<any>('infra/helm/api-gateway/values-staging.yaml');
    expect(String(v.image.tag)).not.toContain('{{');
    expect(String(v.image.tag)).not.toContain('$');
  });

  test('1.7-INT-005: bump service list == B3 Application list (single source)', () => {
    const wf = readRepoFile(DEPLOY_WF);
    // Both the bump (update-helm-values) and sync (trigger-argocd-sync) iterate
    // the SAME Application inventory dir → a service can't be bumped-but-not-synced.
    expect((wf.match(new RegExp(`find ${APPS_DIR.replace(/\//g, '\\/')}`, 'g')) || []).length).toBeGreaterThanOrEqual(2);
  });

  test('[BLIND-SPOT] 1.7-BLIND-BOUNDARY-002: unreplaced placeholder blocked by static grep BEFORE entering sync path', () => {
    const wf = readRepoFile(DEPLOY_WF);
    // Pre-sync guard greps for a residual ${ACR_REGISTRY} token and fails closed.
    const syncIdx = wf.indexOf('argocd app sync "$name"');
    const guardIdx = wf.indexOf("grep -q '${ACR_REGISTRY}'");
    expect(guardIdx).toBeGreaterThan(-1);
    expect(guardIdx).toBeLessThan(syncIdx);
  });
});

// ============================================================
// AC5 (B5): Ingress 模板 + staging DNS/TLS
// ============================================================

describe('AC5 (B5): Ingress template + staging DNS/TLS', () => {
  const ING_TMPL = 'infra/helm/api-gateway/templates/ingress.yaml';

  test('1.7-UNIT-040: api-gateway templates/ingress.yaml exists; values expose ingress.*', () => {
    expect(repoFileExists(ING_TMPL)).toBe(true);
    const v = loadYaml<any>('infra/helm/api-gateway/values.yaml');
    expect(v.ingress).toBeDefined();
    expect(v.ingress.enabled).toBe(false); // default off
  });

  test('1.7-UNIT-041: ingressClassName set (e.g. ingress-nginx)', () => {
    expect(readRepoFile(ING_TMPL)).toContain('ingressClassName');
    const vs = loadYaml<any>('infra/helm/api-gateway/values-staging.yaml');
    expect(vs.ingress.className).toBe('ingress-nginx');
  });

  test('1.7-UNIT-042: api-gateway values-staging FORBIDDEN:ingress.* whitelist lifted + comment de-drifted (1.7 not 1.4)', () => {
    const raw = readRepoFile('infra/helm/api-gateway/values-staging.yaml');
    // ingress is now enabled (whitelist lifted) and attributed to 1.7.
    const vs = loadYaml<any>('infra/helm/api-gateway/values-staging.yaml');
    expect(vs.ingress.enabled).toBe(true);
    expect(raw).not.toMatch(/FORBIDDEN[\s\S]*ingress\.\*\s+—\s+Story 1\.4 adds ingress-nginx/);
    expect(raw).toMatch(/owns ingress|ingress.*Story 1\.7|NOT 1\.4/i);
  });

  test('1.7-UNIT-043: TLS source documented (cert-manager Issuer/ClusterIssuer or preset Secret) in Dev Notes', () => {
    const story = readRepoFile(STORY);
    expect(story).toMatch(/cert-manager/i);
    expect(story).toMatch(/ClusterIssuer|Issuer|secretName/);
  });

  test('1.7-UNIT-044: only externally-exposed svc (api-gateway) get Ingress; internal svc not exposed', () => {
    for (const c of helmCharts()) {
      const tmpl = `${HELM_DIR}/${c}/templates/ingress.yaml`;
      if (c === 'api-gateway') expect(repoFileExists(tmpl)).toBe(true);
      else expect(repoFileExists(tmpl), `${c} should NOT expose Ingress`).toBe(false);
    }
  });

  test('1.7-INT-006: api-gateway staging renders Ingress with staging host + TLS (secretName/issuer) [CI: helm template | kubeconform]', () => {
    const tmpl = readRepoFile(ING_TMPL);
    expect(tmpl).toContain('kind: Ingress');
    expect(tmpl).toMatch(/\.Values\.ingress\.hosts/);
    expect(tmpl).toMatch(/\.Values\.ingress\.tls/);
    const vs = loadYaml<any>('infra/helm/api-gateway/values-staging.yaml');
    expect(vs.ingress.hosts[0].host).toMatch(/staging\.he-api\.com$/);
    expect(vs.ingress.tls[0].secretName).toBeTruthy();
    expect(vs.ingress.annotations['cert-manager.io/cluster-issuer']).toBeTruthy();
  });

  test('1.7-INT-007: ingress disabled (default values.yaml) → no Ingress rendered', () => {
    const v = loadYaml<any>('infra/helm/api-gateway/values.yaml');
    expect(v.ingress.enabled).toBe(false);
    // Template is guarded by `if .Values.ingress.enabled`.
    expect(readRepoFile(ING_TMPL)).toMatch(/{{-?\s*if\s+\.Values\.ingress\.enabled/);
  });

  test('[BLIND-SPOT] 1.7-BLIND-BOUNDARY-003: ingress.enabled true but missing host/TLS → render fails loudly (not silently broken)', () => {
    // The template builds rules ONLY by ranging .Values.ingress.hosts[].host; an
    // enabled-but-hostless config renders an Ingress with no rules → kubeconform/
    // apiserver rejects it (loud failure, not a silent no-op). The staging values
    // DO provide host+TLS, so the happy path renders a valid resource.
    const tmpl = readRepoFile(ING_TMPL);
    expect(tmpl).toMatch(/range \.Values\.ingress\.hosts/);
    expect(tmpl).toMatch(/host:/);
  });
});

