describe('AC7 (B7): payment-svc Helm chart + 5 payment secrets', () => {
  const CHART = 'infra/helm/payment-svc';

  test('1.7-UNIT-060: payment-svc chart exists (Chart.yaml + templates + values.yaml + values-staging.yaml)', () => {
    for (const f of [
      'Chart.yaml',
      'values.yaml',
      'values-staging.yaml',
      'templates/_helpers.tpl',
      'templates/deployment.yaml',
      'templates/service.yaml',
      'templates/serviceaccount.yaml',
      'templates/networkpolicy.yaml',
    ]) {
      expect(repoFileExists(`${CHART}/${f}`), f).toBe(true);
    }
  });

  test('1.7-UNIT-061: 5 payment secrets NEVER plaintext in values; via envFrom/secretRef to out-of-band Secret', () => {
    const dep = readRepoFile(`${CHART}/templates/deployment.yaml`);
    expect(dep).toMatch(/envFrom/);
    expect(dep).toMatch(/secretRef/);
    // No real secret material in values (only key NAMES in requiredKeys, no values).
    const vraw = readRepoFile(`${CHART}/values.yaml`) + readRepoFile(`${CHART}/values-staging.yaml`);
    expect(vraw).not.toMatch(/sk_(live|test)_/);
    expect(vraw).not.toMatch(/whsec_/);
    const v = loadYaml<any>(`${CHART}/values.yaml`);
    expect(Array.isArray(v.paymentProvider.requiredKeys)).toBe(true);
    // The chart renders no Secret object (the Secret is out-of-band).
    expect(repoFileExists(`${CHART}/templates/secret.yaml`)).toBe(false);
  });

  test('1.7-UNIT-062: payment-svc chart structure aligned with auth-svc (Pod Security Restricted, OTel, ServiceMonitor)', () => {
    const dep = readRepoFile(`${CHART}/templates/deployment.yaml`);
    expect(dep).toMatch(/runAsNonRoot: true/);
    expect(dep).toMatch(/readOnlyRootFilesystem: true/);
    expect(dep).toMatch(/OTEL_EXPORTER_OTLP_ENDPOINT/);
    expect(repoFileExists(`${CHART}/templates/servicemonitor.yaml`)).toBe(true);
  });

  test('1.7-INT-009: secretRef key names EXACTLY match apps/payment-svc env var names', () => {
    const v = loadYaml<any>(`${CHART}/values.yaml`);
    const required: string[] = v.paymentProvider.requiredKeys;
    // Env var names actually read by the provider wiring.
    const main = readRepoFile('apps/payment-svc/cmd/server/main.go');
    const codeEnv = new Set([...main.matchAll(/os\.Getenv\("([A-Z0-9_]+)"\)/g)].map((m) => m[1]));
    for (const k of required) {
      expect(codeEnv.has(k), `requiredKey ${k} not read by payment-svc code`).toBe(true);
    }
    // Spot-check the families the test design calls out.
    expect(required).toContain('STRIPE_SECRET_KEY');
    expect(required).toContain('STRIPE_WEBHOOK_SIGNING_SECRET');
    expect(required).toContain('WECHAT_PAY_MCH_ID');
    expect(required).toContain('WECHAT_PAY_APIV3_KEY');
  });

  test('1.7-INT-010: payment-svc helm lint + template renders [CI: helm template | kubeconform]', () => {
    expect(() => loadYaml(`${CHART}/Chart.yaml`)).not.toThrow();
    expect(() => loadYaml(`${CHART}/values.yaml`)).not.toThrow();
    expect(loadYaml<any>(`${CHART}/Chart.yaml`).name).toBe('payment-svc');
  });

  test('1.7-E2E-001: payment-svc present in ALL four single-source lists (B2 matrix / B3 Application / B4 SHA bump / values-staging)', () => {
    expect(nonSampleMatrix().some((e) => e.name === 'payment-svc')).toBe(true); // B2
    expect(repoFileExists(`${APPS_DIR}/payment-svc.yaml`)).toBe(true); // B3
    expect(repoFileExists(`${CHART}/values-staging.yaml`)).toBe(true); // values-staging
    // B4 SHA bump — covered because the bump iterates the Application inventory,
    // which includes payment-svc → its values-staging image gets bumped.
    const app = loadApp('payment-svc.yaml');
    expect(app.spec.source.helm.valueFiles).toContain('values-staging.yaml');
  });

  test('[BLIND-SPOT] 1.7-BLIND-ERROR-006: payment Secret missing → CreateContainerConfigError documented as ops prereq; chart only wires secretRef', () => {
    const doc = readRepoFile('docs/dev/secrets/payment-provider.md');
    expect(doc).toMatch(/envFrom|secretRef/);
    // Chart references the Secret but does not create it.
    expect(repoFileExists(`${CHART}/templates/secret.yaml`)).toBe(false);
    const v = loadYaml<any>(`${CHART}/values.yaml`);
    expect(v.paymentProvider.secretName).toBeTruthy();
  });
});

