// ============================================================
// Cross-AC / Boundary (T8, T9)
// ============================================================

describe('Cross-AC / Boundary (T8, T9)', () => {
  test('1.7-E2E-003: T8.1 — build-matrix images ⊆ ArgoCD Applications ⊆ values-staging SHA-bump (tri-count consistent)', () => {
    // Every non-sample build image's `he-api/<name>` repository must appear in
    // SOME values-staging.yaml (main service or cron sub-image block) — proving
    // build ⊆ values-staging SHA-bump (the bump iterates the Application set, and
    // every Application has a values-staging.yaml → Application ⊆ values-staging).
    const stagingRepos: string[] = [];
    for (const c of readdirSync(repoPath(HELM_DIR))) {
      const vs = `${HELM_DIR}/${c}/values-staging.yaml`;
      if (repoFileExists(vs)) stagingRepos.push(...collectRepositories(loadYaml<any>(vs)));
    }
    for (const e of nonSampleMatrix()) {
      const found = stagingRepos.some((r) => r.endsWith(`/he-api/${e.name}`) || r.endsWith(`he-api/${e.name}`));
      expect(found, `build image ${e.name} not bumped in any values-staging`).toBe(true);
    }
    // Application ⊆ values-staging: every Application's chart has a values-staging.
    for (const app of allApps()) {
      expect(repoFileExists(`${app.spec.source.path}/values-staging.yaml`), app.spec.source.path).toBe(true);
    }
  });

  test('1.7-E2E-005: T8.4 — OUT-OF-SCOPE guard: no envs/prod touched, no values-prod / prod ArgoCD app added', () => {
    for (const c of readdirSync(repoPath(HELM_DIR))) {
      expect(repoFileExists(`${HELM_DIR}/${c}/values-prod.yaml`), `${c} values-prod`).toBe(false);
    }
    for (const f of listAppFiles()) {
      expect(f).not.toMatch(/prod/);
    }
    expect(readRepoFile(DEPLOY_WF)).not.toMatch(/envs\/prod|values-prod/);
  });

  test('1.7-UNIT-080: T8.2 — repo-wide grep aggregate: no tag:latest, no unreplaced placeholder, no "real CLI wired in Story 1.4"', () => {
    for (const f of valuesFiles()) {
      const parsed = loadYaml<any>(f);
      for (const tag of collectTags(parsed)) expect(tag, f).not.toBe('latest');
      for (const repo of collectRepositories(parsed)) expect(repo, f).not.toContain('$$');
    }
    expect(readRepoFile(DEPLOY_WF)).not.toContain(PLACEHOLDER);
    expect(readRepoFile(BUILD_WF)).not.toContain(PLACEHOLDER);
  });

  test('1.7-UNIT-081: T9.2 — all affected workflows actionlint / YAML parse green', () => {
    expect(() => loadYaml(BUILD_WF)).not.toThrow();
    expect(() => loadYaml(DEPLOY_WF)).not.toThrow();
  });

  test('1.7-INT-013: T9.1 — all affected charts parse + have Chart.yaml [CI: helm lint + helm template | kubeconform]', () => {
    for (const c of ['payment-svc', 'analytics-svc', 'billing-svc', 'api-gateway', 'auth-svc']) {
      expect(repoFileExists(`${HELM_DIR}/${c}/Chart.yaml`), c).toBe(true);
      expect(() => loadYaml(`${HELM_DIR}/${c}/values.yaml`), c).not.toThrow();
      expect(() => loadYaml(`${HELM_DIR}/${c}/values-staging.yaml`), c).not.toThrow();
    }
  });

  test('[BLIND-SPOT] 1.7-BLIND-DATA-002: every spec.project: he-api reference resolves to the he-api AppProject (no orphan project ref)', () => {
    const proj = loadYaml<any>('infra/argocd/projects/he-api.yaml');
    expect(proj.metadata.name).toBe('he-api');
    for (const app of allApps()) {
      expect(app.spec.project).toBe('he-api');
    }
  });
});
